('Phonics Songs & Chants','ai·ay와 a_e 비교 복습','ai·ay를 배우고 이전 a_e와 비교해요. 같은 긴 a 소리를 서로 다른 철자로 찾아요.','m-uLFJp5ZtI','English4abc',0,146,5,ARRAY['classbank:phonics-song'],'','{}'::text[],'{"phonicsSong": {"unitIds": ["course-5-2"], "purpose": "review", "tip": "ai·ay를 배우고 이전 a_e와 비교해요. 같은 긴 a 소리를 서로 다른 철자로 찾아요.", "ruleIds": ["vowel-ai", "vowel-ay"], "sourceTitle": "Long Vowel Letter a - ai/a-e/ay - English4abc - Phonics song", "catalog": "phonics-core-2026-10", "verifiedAt": "2026-10-29"}}'::jsonb,27),
